add('11_003',1.5,'16:9，贴近石铺地面的低机位全景，扇形掀起的大石占画面左下与中央，武士宽立的小轮廓留在右上远层；固定机位。','青原先立足处只闪过一抹银白发色与粉紫衣色的薄残形，下一瞬便空了；蹬力把几块石板从左下猛掀成扇面，碎石从板缝迸起，白色斜向速度划线直掠武士方向。远处武士保持宽立姿态，双臂仍垂在原位，残形随石屑的升起迅速擦净。','灰绿石铺地面延向右上，掀起的石板断面米灰、板缝深灰；远层一条蓝灰云天从平台上缘露出。','正上方云天冷白漫射，石板立起后背面转深冷灰，飞屑亮暗清楚。','脚下骤裂一声脆轰，接碎石急促迸响和一记短利破风。',node={'叙事阶段':'青蹬地后高速消失于起点','武士.位置':'原地宽立，双臂位置稳定'},meaning='青以残影瞬移观感从起点骤然离开，武士不攻击也不改站位。',motion='残形与速度线由左下起点斜向右上掠出，石板只在起点向上爆开。',ground='青起脚蹬地；武士远处双脚保持着地。',characters=['青','鬼头武士'])
add('12_001',1,'16:9，武士椭圆头部的侧面极特写，弧面占中央到画面右侧，左端只留一线黑隙与小白眼；固定机位，远处背景压为平整浅底。','武士白眼先停在原先朝前的方向，一小拍后，眼珠沿黑隙朝身后侧滑动；头的厚重轮廓保持原位，眼珠停住的瞬间黑隙边缘收紧，下一镜才接完整回头。','头部下沿与左端以外是均匀浅蓝灰图形底场，稀薄云纹退成软面。','同场冷白柔光铺在头部弧面，黑隙保持深黑，小白眼清晰。','上一声破风的短尾从画外掠过，随后只有一口低沉呼吸。',phase='reaction',node={'叙事阶段':'武士先察觉身后声位','武士.位置':'原地站立'},meaning='武士视线特写先感知青已越过，固定姿态中只有眼神反应。',motion='眼珠在头部黑隙内向背后侧滑，身体没有位移。',characters=['鬼头武士'])
add('12_002',2.5,'16:9，武士背肩与青同框的低机位中全景，巨大背与近臂占中央和画面左侧，青在右后腰际；固定机位，留清青的全身与回头的白眼。','青在武士右后方忽然凝实，银白长发和粉紫裙角各留一道薄残形，残形擦过后才是稳定身体；她腿位撑开、上身前倾，一臂抬在肩侧，另一臂向下展出，吐字清楚地提醒背后。武士双脚与双臂维持宽立姿态，只把头沿颈轴向青转回，白眼落到她身上；青的发尾晚一拍追过身体，手指开始握紧。','灰绿石铺地面在两人下缘与左侧臂外露出，原有米灰薄尘贴着石面缓散；上方一小块蓝灰云天，远层不添近处建筑。','正上方冷白漫射在武士背肩与青银发形成宽软亮面，背下侧为深冷灰，石面弱补光托住青脸侧。','高速到位一记短促风切声，青鞋底轻擦石面，发梢余风迅速平息。',ja=['後ろだよ。'],tone='青声线清楚，带抢到先机的轻快提醒，短句落定后立即凝神。',kind='mixed',node={'叙事阶段':'青已到武士背后并开口','青.位置':'武士右后侧，站稳准备拉拳','武士.位置':'原地站姿，只有头回转'},meaning='用户纠正：青残影瞬间到背后，武士只回头，无粗臂落空或身体转位。',motion='青先以残形闪到右后，再凝实；武士头转向右后，脚与臂不跟转。',ground='青双脚落在武士后侧石面；武士双脚仍在原位承重。',characters=['青','鬼头武士'],card={'opening':'青取得速度优势，从背后夺走注意。','beats':['残影擦净后稳住腿位，短句提醒','武士只转头，青指尖握紧'],'coupling':'声音让武士的回头完成，青已在准备下一动作。','landing':'青在背后拉拳前，武士刚看见她。'})
